import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // 1. Collect inputs
        System.out.print("Enter Employee ID: ");
        int empId = scanner.nextInt();
        scanner.nextLine(); // Clear buffer

        System.out.print("Enter Employee Name: ");
        String name = scanner.nextLine();

        System.out.print("Enter Basic Monthly Salary: ");
        double basicSalary = scanner.nextDouble();

        // 2. Compute allowances and deductions
        double hra = basicSalary * 0.20; // 20% HRA
        double da = basicSalary * 0.10;  // 10% DA
        double grossSalary = basicSalary + hra + da;
        double tax = grossSalary * 0.05;  // 5% income tax
        double pf = basicSalary * 0.12;   // 12% Provident Fund
        double totalDeductions = tax + pf;
        double netSalary = grossSalary - totalDeductions;

        // 3. Print formatted salary slip
        System.out.println("\n========================================");
        System.out.printf("           SALARY PAY SLIP              %n");
        System.out.println("========================================");
        System.out.printf("Employee ID:   #%05d%n", empId);
        System.out.printf("Employee Name: %s%n", name);
        System.out.println("----------------------------------------");
        System.out.printf("%-20s : Rs %10.2f%n", "Basic Salary", basicSalary);
        System.out.printf("%-20s : Rs %10.2f%n", "HRA (20%)", hra);
        System.out.printf("%-20s : Rs %10.2f%n", "DA (10%)", da);
        System.out.println("----------------------------------------");
        System.out.printf("%-20s : Rs %10.2f%n", "Gross Salary", grossSalary);
        System.out.printf("%-20s : Rs %10.2f%n", "Tax (5%)", tax);
        System.out.printf("%-20s : Rs %10.2f%n", "PF (12%)", pf);
        System.out.println("----------------------------------------");
        System.out.printf("%-20s : Rs %10.2f%n", "NET TAKE-HOME PAY", netSalary);
        System.out.println("========================================");

        scanner.close();
    }
}

