import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int amt = scanner.nextInt();
        int n500 = amt / 500;
        int rem1 = amt % 500;
        int n100 = rem1 / 100;
        int rem2 = rem1 % 100;
        System.out.println("500s: " + n500 + ", 100s: " + n100 + ", Remaining: " + rem2);
        scanner.close();
    }
}

